// Each release body starts with its own `# vX.Y.Z` H1, which is right for the
// standalone /releases/<x.y.z> page but would give this feed one H1 per release.
// Here we shift every body heading down two levels so the posts nest under the
// month <h2> (h1 -> h3, h2 -> h4, h3 -> h5, h4+ -> h6). The classes keep the
// demoted headings looking like they did as h1/h2/h3 (see globals.css), and
// `release-heading` keeps them picked up by HeadingAnchors. The release .mdx
// files are generated by automation, so the shift lives here, not in them.
// A post must not skip levels itself (`#` then `##`, never `#` then `###`), or
// the skip carries into the feed; tests/heading-structure.test.jsx checks this.
const demote = (Tag, classes) =>
  function DemotedHeading({ className, ...props }) {
    const merged = [classes, className].filter(Boolean).join(" ");
    return <Tag {...props} className={merged || undefined} />;
  };

export const demotedHeadings = {
  h1: demote("h3", "release-heading release-title"),
  h2: demote("h4", "release-heading release-section"),
  h3: demote("h5", "release-heading release-subsection"),
  h4: demote("h6"),
  h5: demote("h6"),
  h6: demote("h6"),
};
